var mass = [];
var positionX = [];
var positionY = [];
var velocityX = [];
var velocityY = [];

const frequency = 10 ;
const max_auto  = 100

const palette = [
	/*['#FFF8E1', '#FFECB3', '#FFE082'],*/[
		'#FFD54F', '#FFCA28', '#FFC107'],
	['#FFB300', '#FFA000', '#FF8F00'],
	/*['#E3F2FD', '#BBDEFB', '#90CAF9'],*/
	['#64B5F6', '#42A5F5', '#2196F3'],
	['#1E88E5', '#1976D2', '#1565C0'],
	/*['#FFEBEE', '#FFCDD2', '#EF9A9A'],*/
	['#E57373', '#EF5350', '#F44336'],
	['#E53935', '#D32F2F', '#C62828'],
	/*['#E8F5E9', '#C8E6C9', '#A5D6A7'],*/
	['#81C784', '#66BB6A', '#4CAF50'],
	['#43A047', '#388E3C', '#2E7D32'],
	 /*['#FFF3E0', '#FFE0B2', '#FFCC80'],*/
	['#FFB74D', '#FFA726', '#FF9800'],
	['#FB8C00', '#F57C00', '#EF6C00'],
	 /*['#F3E5F5', '#E1BEE7', '#CE93D8'],*/
	['#BA68C8', '#AB47BC', '#9C27B0'],
	['#8E24AA', '#7B1FA2', '#6A1B9A']
];

/////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowHeight*4/3, windowHeight);
	noStroke();
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
	background(32, 20);

	fill(64, 255, 255, 192);
	for (var particleA = 0; particleA < mass.length; particleA++) {
		var accelerationX = 0, accelerationY = 0;

		for (var particleB = 0; particleB < mass.length; particleB++) {
			if (particleA != particleB) {
				var distanceX = positionX[particleB] - positionX[particleA];
				var distanceY = positionY[particleB] - positionY[particleA];

				var distance = sqrt(distanceX * distanceX + distanceY * distanceY);
				if (distance < 1) distance = 1;

				var force = (distance - 320) * mass[particleB] / distance;
				accelerationX += force * distanceX;
				accelerationY += force * distanceY;
			}
		}

		velocityX[particleA] = velocityX[particleA] * 0.99 + accelerationX * mass[particleA];
		velocityY[particleA] = velocityY[particleA] * 0.99 + accelerationY * mass[particleA];
	}

	for (var particle = 0; particle < mass.length; particle++) {
		positionX[particle] += velocityX[particle];
		positionY[particle] += velocityY[particle];

		let col = palette[ particle % palette.length ] ;

		fill(color(random(col)))

		ellipse(positionX[particle], positionY[particle], mass[particle] * 1000, mass[particle] * 1000);
	}

	fill(255);
	text(mass.length, 20,20)

	if (mass.length < max_auto  && frameCount%frequency == 0) {
		let x = random(width)
		let y = random(height)
		addNewParticle(x,y) 
	} else {
		if (mass.length > max_auto) {
			fill(255);
			text("Click or drag to add more", 20,40)
		}
	}


}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function addNewParticle(x,y) {
	mass.push(random(0.003, 0.03));
	positionX.push(x);
	positionY.push(y);
	velocityX.push(0);
	velocityY.push(0);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseClicked() {
	addNewParticle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseDragged() {
	addNewParticle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

